package sframe

import (
	"bytes"
	"encoding/hex"
	"errors"
	"testing"
)

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad hex %q: %v", s, err)
	}
	return b
}

// Known-answer vectors from docs/SFRAME_CALLS_M0_KEY_DISTRIBUTION.md §3.4,
// generated by JS WebCrypto and cross-checked against lksdk.
func TestDeriveKeyKnownAnswer(t *testing.T) {
	secret := mustHex(t, "000102030405060708090a0b0c0d0e0f")
	want := mustHex(t, "4086b4641064e1ae8b63d4eb83ad3e7e")

	key, err := DeriveKey(secret)
	if err != nil {
		t.Fatalf("DeriveKey: %v", err)
	}
	if !bytes.Equal(key, want) {
		t.Fatalf("derived key = %x, want %x", key, want)
	}
}

func TestSealKnownAnswer(t *testing.T) {
	key := mustHex(t, "4086b4641064e1ae8b63d4eb83ad3e7e")
	iv := mustHex(t, "000102030405060708090a0b")
	plaintext := mustHex(t, "f80102030405060708090a0b0c0d0e0f10111213")
	want := mustHex(t, "f83524ddffa627b64c723a6827f452b6815aa11ba7a509b49b16fa6bab7ec5138f36fa77"+
		"000102030405060708090a0b0c07")

	frame, err := SealWithIV(plaintext, key, 7, iv)
	if err != nil {
		t.Fatalf("SealWithIV: %v", err)
	}
	if !bytes.Equal(frame, want) {
		t.Fatalf("sealed frame = %x, want %x", frame, want)
	}
}

func TestOpenKnownAnswer(t *testing.T) {
	key := mustHex(t, "4086b4641064e1ae8b63d4eb83ad3e7e")
	frame := mustHex(t, "f83524ddffa627b64c723a6827f452b6815aa11ba7a509b49b16fa6bab7ec5138f36fa77"+
		"000102030405060708090a0b0c07")
	want := mustHex(t, "f80102030405060708090a0b0c0d0e0f10111213")

	plaintext, kid, err := Open(frame, key)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	if kid != 7 {
		t.Fatalf("kid = %d, want 7", kid)
	}
	if !bytes.Equal(plaintext, want) {
		t.Fatalf("plaintext = %x, want %x", plaintext, want)
	}
}

func TestSealOpenRoundTrip(t *testing.T) {
	key := mustHex(t, "4086b4641064e1ae8b63d4eb83ad3e7e")

	for _, size := range []int{1, 2, 3, 20, 127, 128, 1000} {
		payload := make([]byte, size)
		payload[0] = 0xf8 // Opus TOC, the authenticated cleartext byte
		for i := 1; i < size; i++ {
			payload[i] = byte(i*7 + 3)
		}

		frame, err := Seal(payload, key, 3)
		if err != nil {
			t.Fatalf("size %d: Seal: %v", size, err)
		}
		if got, want := len(frame), len(payload)+FrameOverhead; got != want {
			t.Fatalf("size %d: frame len = %d, want %d", size, got, want)
		}
		if FrameOverhead != 30 {
			t.Fatalf("FrameOverhead = %d, want 30", FrameOverhead)
		}

		plaintext, kid, err := Open(frame, key)
		if err != nil {
			t.Fatalf("size %d: Open: %v", size, err)
		}
		if kid != 3 {
			t.Fatalf("size %d: kid = %d, want 3", size, kid)
		}
		if !bytes.Equal(plaintext, payload) {
			t.Fatalf("size %d: round trip mismatch", size)
		}
	}
}

func TestSealUsesFreshIV(t *testing.T) {
	key := mustHex(t, "4086b4641064e1ae8b63d4eb83ad3e7e")
	payload := mustHex(t, "f8010203")

	first, err := Seal(payload, key, 0)
	if err != nil {
		t.Fatalf("Seal: %v", err)
	}
	second, err := Seal(payload, key, 0)
	if err != nil {
		t.Fatalf("Seal: %v", err)
	}
	if bytes.Equal(first, second) {
		t.Fatal("two seals produced identical frames; IV is not random")
	}
}

func TestSealValidation(t *testing.T) {
	key := make([]byte, AESKeySize)
	if _, err := Seal(nil, key, 0); !errors.Is(err, ErrEmptyFrame) {
		t.Fatalf("empty payload error = %v, want ErrEmptyFrame", err)
	}
	if _, err := Seal([]byte{0xf8}, key[:15], 0); !errors.Is(err, ErrKeySize) {
		t.Fatalf("short key error = %v, want ErrKeySize", err)
	}
	if _, err := SealWithIV([]byte{0xf8}, key, 0, make([]byte, IVSize-1)); !errors.Is(err, ErrIVSize) {
		t.Fatalf("short IV error = %v, want ErrIVSize", err)
	}
}

func TestOpenRejectsGarbage(t *testing.T) {
	key := make([]byte, AESKeySize)

	for size := 0; size < 31; size++ {
		frame := bytes.Repeat([]byte{0xab}, size)
		if _, _, err := Open(frame, key); err == nil {
			t.Fatalf("Open accepted %d-byte frame", size)
		}
	}

	valid, err := Seal([]byte{0xf8, 0x00}, key, 0)
	if err != nil {
		t.Fatalf("Seal: %v", err)
	}

	noIV := append([]byte(nil), valid...)
	noIV[len(noIV)-2] = 0
	if _, _, err := Open(noIV, key); !errors.Is(err, ErrIVLength) {
		t.Fatalf("zero IV length error = %v, want ErrIVLength", err)
	}

	hugeIV := append([]byte(nil), valid...)
	hugeIV[len(hugeIV)-2] = 250
	if _, _, err := Open(hugeIV, key); !errors.Is(err, ErrIVLength) {
		t.Fatalf("oversized IV length error = %v, want ErrIVLength", err)
	}

	if _, _, err := Open(valid, key[:8]); !errors.Is(err, ErrKeySize) {
		t.Fatalf("short key error = %v, want ErrKeySize", err)
	}
}

func TestOpenRejectsTampering(t *testing.T) {
	key := mustHex(t, "4086b4641064e1ae8b63d4eb83ad3e7e")
	payload := mustHex(t, "f80102030405060708090a0b0c0d0e0f10111213")

	frame, err := SealWithIV(payload, key, 7, mustHex(t, "000102030405060708090a0b"))
	if err != nil {
		t.Fatalf("SealWithIV: %v", err)
	}
	ivStart := len(frame) - 2 - IVSize

	positions := map[string]int{
		"toc (AAD)":       0,
		"ciphertext head": 1,
		"ciphertext tail": ivStart - 1,
		"iv head":         ivStart,
		"iv tail":         ivStart + IVSize - 1,
		"iv length byte":  len(frame) - 2,
	}
	for name, pos := range positions {
		tampered := append([]byte(nil), frame...)
		tampered[pos] ^= 0x01
		if _, _, err := Open(tampered, key); err == nil {
			t.Fatalf("%s tampering accepted", name)
		}
	}
}

func TestOpenWrongKey(t *testing.T) {
	key := mustHex(t, "4086b4641064e1ae8b63d4eb83ad3e7e")
	other := mustHex(t, "00000000000000000000000000000000")
	frame, err := Seal([]byte{0xf8, 0x01}, key, 0)
	if err != nil {
		t.Fatalf("Seal: %v", err)
	}
	if _, _, err := Open(frame, other); !errors.Is(err, ErrDecrypt) {
		t.Fatalf("wrong key error = %v, want ErrDecrypt", err)
	}
}

func TestKIDIsNotAuthenticated(t *testing.T) {
	key := mustHex(t, "4086b4641064e1ae8b63d4eb83ad3e7e")
	frame, err := SealWithIV([]byte{0xf8, 0x01}, key, 7, mustHex(t, "000102030405060708090a0b"))
	if err != nil {
		t.Fatalf("SealWithIV: %v", err)
	}

	tampered := append([]byte(nil), frame...)
	tampered[len(tampered)-1] = 9
	plaintext, kid, err := Open(tampered, key)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	if kid != 9 {
		t.Fatalf("kid = %d, want 9", kid)
	}
	if !bytes.Equal(plaintext, []byte{0xf8, 0x01}) {
		t.Fatalf("plaintext changed: %x", plaintext)
	}
}

func TestIsSIF(t *testing.T) {
	trailer := mustHex(t, "deadbeefcafe")
	frame := append([]byte{0xf8, 0x01, 0x02}, trailer...)

	if !IsSIF(frame, trailer) {
		t.Fatal("IsSIF = false for frame with trailer")
	}
	if IsSIF(frame[:len(frame)-1], trailer) {
		t.Fatal("IsSIF = true for frame without trailer")
	}
	if IsSIF(frame, nil) {
		t.Fatal("IsSIF = true with nil trailer")
	}
	if IsSIF(frame, []byte{}) {
		t.Fatal("IsSIF = true with empty trailer")
	}
	if !IsSIF(trailer, trailer) {
		t.Fatal("IsSIF = false when frame is exactly the trailer")
	}
}
